// Attached to the main export is a `strided` method which returns a collection...
{
	const z1 = new Float64Array( 2 );
	const z2 = new Float64Array( z1.length );
	const z3 = new Float64Array( z1.length );
	const z4 = new Float64Array( z1.length );

	add4.strided( z1, 1, 0, z2, 1, 0, z3, 1, 0, z4, 1, 0, new Float64Array( 2 ), 1, 0 ); // $ExpectType Float64Array
	add4.strided( z1, 1, 0, z2, 1, 0, z3, 1, 0, z4, 1, 0, new Float32Array( 2 ), 1, 0 ); // $ExpectType Float32Array
	add4.strided( z1, 1, 0, z2, 1, 0, z3, 1, 0, z4, 1, 0, [ 0.0, 0.0 ], 1, 0 ); // $ExpectType number[]
}

